const CATALOG_URL='https://tarktee.transpordiamet.ee/tarktee/rest/services/tram/road_cameras/MapServer/0/query?where=1%3D1&outFields=*&outSR=4326&returnGeometry=true&f=geojson';
const IMAGE_BASE='https://tarktee.transpordiamet.ee/images/';
const FALLBACK=[
 {id:'fallback-tallinn',name:'Tallinn',lat:59.437,lon:24.7536,image:'',source:'https://tarktee.transpordiamet.ee/'},
 {id:'fallback-tartu',name:'Tartu',lat:58.3776,lon:26.729,image:'',source:'https://tarktee.transpordiamet.ee/'},
 {id:'fallback-parnu',name:'Pärnu',lat:58.3859,lon:24.4971,image:'',source:'https://tarktee.transpordiamet.ee/'}
];
let cameras=[],userLocation=null,deferredPrompt=null;
const $=s=>document.querySelector(s);
const list=$('#cameraList'),status=$('#status'),markers=$('#markers');

function getProp(p,...keys){for(const k of keys){const match=Object.keys(p||{}).find(x=>x.toLowerCase()===k.toLowerCase());if(match&&p[match]!=null)return p[match]}return ''}
function normalize(feature,i){const p=feature.properties||{},c=feature.geometry?.coordinates||[];let image=getProp(p,'image_path','imagepath','image','url','latest_image');if(image&&!/^https?:/i.test(image)) image=IMAGE_BASE+String(image).replace(/^\/+|^images\//,'');return{id:String(getProp(p,'objectid','id')||i),name:String(getProp(p,'site_name','name','camera_name','title')||`Teekaamera ${i+1}`),lat:Number(c[1]??getProp(p,'latitude','lat')),lon:Number(c[0]??getProp(p,'longitude','lon','lng')),image,source:'https://tarktee.transpordiamet.ee/'} }
function distance(a,b){const R=6371,dLat=(b.lat-a.lat)*Math.PI/180,dLon=(b.lon-a.lon)*Math.PI/180;const x=Math.sin(dLat/2)**2+Math.cos(a.lat*Math.PI/180)*Math.cos(b.lat*Math.PI/180)*Math.sin(dLon/2)**2;return 2*R*Math.asin(Math.sqrt(x))}
function filtered(){const q=$('#searchInput').value.trim().toLowerCase(),r=Number($('#radiusSelect').value);return cameras.map(c=>({...c,distance:userLocation?distance(userLocation,c):null})).filter(c=>(!q||c.name.toLowerCase().includes(q))&&(!userLocation||c.distance<=r)).sort((a,b)=>userLocation?a.distance-b.distance:a.name.localeCompare(b.name,'et'))}
function placeholder(name){return `<div style="width:100%;height:100%;display:grid;place-items:center;color:#80f2a9;font-weight:900;font-size:22px">${name.slice(0,2).toUpperCase()}</div>`}
function render(){const data=filtered();$('#cameraCount').textContent=cameras.length||'—';$('#resultTitle').textContent=userLocation?'Sulle lähimad':'Avalikud kaamerad';status.textContent=data.length?`${data.length} kaamerat${userLocation?' valitud raadiuses':''}`:'Sobivaid kaameraid ei leitud';list.innerHTML=data.length?data.slice(0,120).map(c=>`<article class="camera-card" tabindex="0" data-id="${c.id}"><div class="thumb">${c.image?`<img src="${c.image}" alt="${esc(c.name)} kaamerapilt" loading="lazy" referrerpolicy="no-referrer" onerror="this.outerHTML='${placeholder(c.name).replaceAll("'","&apos;")}'">`:placeholder(c.name)}<span class="badge">VÄRSKEIM</span></div><div class="camera-info"><h3>${esc(c.name)}</h3><div class="meta"><span>${c.distance!=null?`${c.distance.toFixed(c.distance<10?1:0)} km kaugusel`:'Eesti'}</span><span>Transpordiamet</span></div></div></article>`).join(''):`<div class="empty">Proovi suuremat raadiust või teist otsingut.</div>`;renderMarkers(data);document.querySelectorAll('.camera-card').forEach(el=>{el.onclick=()=>openCamera(el.dataset.id);el.onkeydown=e=>{if(e.key==='Enter')openCamera(el.dataset.id)}})}
function esc(s){return String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function renderMarkers(data){markers.innerHTML=data.slice(0,160).map(c=>{const x=(c.lon-21.5)/(28.4-21.5)*78+10,y=(59.9-c.lat)/(59.9-57.4)*66+17;return `<button class="marker" style="left:${x}%;top:${y}%" data-id="${c.id}" aria-label="${esc(c.name)}" title="${esc(c.name)}"></button>`}).join('')+(userLocation?`<span class="marker user" style="left:${(userLocation.lon-21.5)/(28.4-21.5)*78+10}%;top:${(59.9-userLocation.lat)/(59.9-57.4)*66+17}%" title="Sinu asukoht"></span>`:'');document.querySelectorAll('.marker[data-id]').forEach(el=>el.onclick=()=>openCamera(el.dataset.id))}
function openCamera(id){const c=cameras.find(x=>x.id===id);if(!c)return;const d=userLocation?distance(userLocation,c):null;$('#dialogBody').innerHTML=`${c.image?`<img class="dialog-img" src="${c.image}?t=${Date.now()}" alt="${esc(c.name)} värskeim kaader" referrerpolicy="no-referrer">`:`<div class="dialog-img" style="height:300px;display:grid;place-items:center">Pilt avaneb allika lehel</div>`}<div class="dialog-copy"><p class="eyebrow">AVALIK TEEKAAMERA</p><h2>${esc(c.name)}</h2><p>${d!=null?`${d.toFixed(1)} km sinu asukohast. `:''}Kuvatakse Transpordiameti värskeim avalik kaader; see ei ole katkematu videovoog.</p><a class="source-link" href="${c.source}" target="_blank" rel="noopener">Ava ametlik allikas</a></div>`;$('#cameraDialog').showModal()}
async function loadCameras(){status.textContent='Laadin Transpordiameti kaameraid…';try{const r=await fetch(CATALOG_URL,{cache:'no-store'});if(!r.ok)throw Error(r.status);const j=await r.json();cameras=(j.features||[]).map(normalize).filter(c=>Number.isFinite(c.lat)&&Number.isFinite(c.lon));if(!cameras.length)throw Error('Tühi andmevoog');status.classList.remove('offline');localStorage.setItem('cameraCache',JSON.stringify({time:Date.now(),cameras}))}catch(e){const cache=JSON.parse(localStorage.getItem('cameraCache')||'null');cameras=cache?.cameras?.length?cache.cameras:FALLBACK;status.classList.add('offline');status.textContent='Andmeallikas pole hetkel kättesaadav — näitan salvestatud vaadet.'}render()}
$('#locateBtn').onclick=()=>{if(!navigator.geolocation){status.textContent='Sinu brauser ei toeta asukoha määramist.';return}status.textContent='Küsin asukohta…';navigator.geolocation.getCurrentPosition(p=>{userLocation={lat:p.coords.latitude,lon:p.coords.longitude};$('#radiusSelect').value='50';render()},e=>{status.textContent=e.code===1?'Asukoha luba jäi andmata. Saad kaameraid siiski otsida.':'Asukohta ei õnnestunud määrata.'},{enableHighAccuracy:true,timeout:10000,maximumAge:300000})};
$('#searchInput').oninput=render;$('#radiusSelect').onchange=render;$('#refreshBtn').onclick=loadCameras;$('#viewToggle').onclick=()=>document.body.classList.toggle('list-only');$('#closeDialog').onclick=()=>$('#cameraDialog').close();$('#cameraDialog').onclick=e=>{if(e.target===$('#cameraDialog'))$('#cameraDialog').close()};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('#installBtn').hidden=false});$('#installBtn').onclick=async()=>{if(deferredPrompt){deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$('#installBtn').hidden=true}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));
loadCameras();
